-- Class rework 2026-10-16 (Codex package rework-2026-10-16, via Cap). LOCKED by Gabriel 2026-10-16.
-- Renames, duplicate replacements, new boost frame (4/8/12/16/20/24/28 + Cap Rise 19/22/29 + Primordial Ascent 29),
-- Primordial Blessings, class choice pools and pick-one-of-three rows. Idempotent: safe to re-run.
BEGIN;

CREATE TABLE IF NOT EXISTS primordial_blessings (
    id SERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, tree TEXT NOT NULL, prerequisite TEXT, description TEXT NOT NULL,
    action_type TEXT, uses TEXT, dice TEXT, repeatable_max INTEGER NOT NULL DEFAULT 1, approved_date DATE);
CREATE TABLE IF NOT EXISTS class_feature_options (
    id SERIAL PRIMARY KEY, class_id INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE, pool TEXT NOT NULL, name TEXT NOT NULL,
    description TEXT NOT NULL, action_type TEXT, uses TEXT, dice TEXT, min_level INTEGER NOT NULL DEFAULT 1, source TEXT, approved_date DATE,
    UNIQUE (class_id, pool, name));

-- 1. Subclass renames
UPDATE sub_classes SET name = 'Weaponmaster' WHERE name = 'Weapons Master ';
UPDATE sub_classes SET name = 'Hollowmancer' WHERE name = 'Hollomancer';
UPDATE sub_classes SET name = 'Oath of Shadows' WHERE name = 'Oath of Shadow';
UPDATE sub_classes SET name = 'Rite of the Archon' WHERE id = 47 AND class_id = 15;
UPDATE sub_classes SET name = 'Rite of the Seraph' WHERE id = 48 AND class_id = 15;
UPDATE sub_classes SET name = 'Rite of the Virtue' WHERE id = 49 AND class_id = 15;
UPDATE class_features SET description = replace(description, 'Archonbound', 'Rite of the Archon') WHERE description LIKE '%Archonbound%';
UPDATE subclass_features SET description = replace(description, 'Archonbound', 'Rite of the Archon') WHERE description LIKE '%Archonbound%';
UPDATE classes SET description = replace(description, 'Archonbound', 'Rite of the Archon') WHERE description LIKE '%Archonbound%';
UPDATE class_features SET description = replace(description, 'Seraphbound', 'Rite of the Seraph') WHERE description LIKE '%Seraphbound%';
UPDATE subclass_features SET description = replace(description, 'Seraphbound', 'Rite of the Seraph') WHERE description LIKE '%Seraphbound%';
UPDATE classes SET description = replace(description, 'Seraphbound', 'Rite of the Seraph') WHERE description LIKE '%Seraphbound%';
UPDATE class_features SET description = replace(description, 'Virtuebound', 'Rite of the Virtue') WHERE description LIKE '%Virtuebound%';
UPDATE subclass_features SET description = replace(description, 'Virtuebound', 'Rite of the Virtue') WHERE description LIKE '%Virtuebound%';
UPDATE classes SET description = replace(description, 'Virtuebound', 'Rite of the Virtue') WHERE description LIKE '%Virtuebound%';
UPDATE class_features SET description = replace(description, 'Hollomancer', 'Hollowmancer') WHERE description LIKE '%Hollomancer%';
UPDATE subclass_features SET description = replace(description, 'Hollomancer', 'Hollowmancer') WHERE description LIKE '%Hollomancer%';
UPDATE classes SET description = replace(description, 'Hollomancer', 'Hollowmancer') WHERE description LIKE '%Hollomancer%';

-- 2. Duplicate replacements (duplicates.csv)
UPDATE class_features f SET name = regexp_replace(f.name, '^Channel Divinity', 'Oath Channel'), description = replace(f.description, 'Channel Divinity', 'Oath Channel')
  FROM classes c WHERE c.id = f.class_id AND c.name = 'Paladin' AND (f.name LIKE 'Channel Divinity%' OR f.description LIKE '%Channel Divinity%');
UPDATE subclass_features f SET description = replace(f.description, 'Channel Divinity', 'Oath Channel')
  FROM sub_classes s JOIN classes c ON c.id = s.class_id WHERE s.id = f.subclass_id AND c.name = 'Paladin' AND f.description LIKE '%Channel Divinity%';
UPDATE class_features f SET name='Oath Channel', description='Your oath channel: 1 use per rest (2 at 13, 3 at 23), spent on your oath options and Oath''s Rebuke.', action_type=NULL, uses='1 per rest', dice=NULL, approved_date=DATE '2026-10-16'
  FROM classes c WHERE c.id = f.class_id AND c.name = 'Paladin' AND f.level = 3 AND f.name IN ('Oath Channel', 'Oath Channel');
UPDATE class_features f SET name='Binding Command', description='Once per turn when you cast a Summoner spell, one summon within 60 ft uses its reaction to move up to half its speed and make one attack.', action_type=NULL, uses='At will (1/turn)', dice='summon''s dice', approved_date=DATE '2026-10-16'
  FROM classes c WHERE c.id = f.class_id AND c.name = 'Summoner' AND f.level = 11 AND f.name IN ('Commander''s Strike', 'Binding Command');
UPDATE class_features f SET name='Rolling Guard', description='When you make a DEX save for half damage: on a success you take none; on a failure you take half, and you can use your reaction to move 10 ft without provoking.', action_type=NULL, uses='At will', dice=NULL, approved_date=DATE '2026-10-16'
  FROM classes c WHERE c.id = f.class_id AND c.name = 'Pugilist' AND f.level = 7 AND f.name IN ('Evasion', 'Rolling Guard');
UPDATE class_features f SET name='Practiced Refrain', description='Choose two proficient skills. When you roll them, treat a d20 roll of 9 or lower as a 10, and add +1d4 once per short rest.', action_type=NULL, uses='1 per short rest (d4)', dice='1d4', approved_date=DATE '2026-10-16'
  FROM classes c WHERE c.id = f.class_id AND c.name = 'Songsmith' AND f.level = 3 AND f.name IN ('Expertise', 'Practiced Refrain');
UPDATE subclass_features f SET name='Challenger''s Brand', description='Bonus action, at will: brand a creature within 30 ft for 1 minute (one at a time). While within 10 ft of you it has disadvantage on attacks against anyone but you.', action_type='bonus', uses='At will', dice=NULL, approved_date=DATE '2026-10-16'
  FROM sub_classes s JOIN classes c ON c.id = s.class_id WHERE s.id = f.subclass_id AND c.name = 'Warrior' AND s.name IN ('Vanguard', 'Vanguard') AND f.level = 3 AND f.name IN ('Hold the Line', 'Challenger''s Brand');
UPDATE subclass_features f SET name='Ranks Unbroken', description='Bonus action, 1 per long rest, 1 minute: an enemy must succeed on a STR save (class DC) to move away from you.', action_type='bonus', uses='1 per long rest', dice=NULL, approved_date=DATE '2026-10-16'
  FROM sub_classes s JOIN classes c ON c.id = s.class_id WHERE s.id = f.subclass_id AND c.name = 'Soul Smith' AND s.name IN ('Mark of Legion', 'Mark of Legion') AND f.level = 18 AND f.name IN ('Hold the Line', 'Ranks Unbroken');
UPDATE subclass_features f SET name='Bedrock Rage', description='While raging: forced movement against you is reduced by 10 ft, you have advantage on checks to shove or grapple, and a creature that fails to move you takes your Rage damage bonus.', action_type=NULL, uses='While raging', dice=NULL, approved_date=DATE '2026-10-16'
  FROM sub_classes s JOIN classes c ON c.id = s.class_id WHERE s.id = f.subclass_id AND c.name = 'Berserker' AND s.name IN ('Ironhide', 'Ironhide') AND f.level = 14 AND f.name IN ('Immovable', 'Bedrock Rage');
UPDATE subclass_features f SET name='Take the Blow', description='Reaction when a creature within 5 ft of you is hit: you become the target and it uses your AC.', action_type='reaction', uses='PB per long rest', dice=NULL, approved_date=DATE '2026-10-16'
  FROM sub_classes s JOIN classes c ON c.id = s.class_id WHERE s.id = f.subclass_id AND c.name = 'Warrior' AND s.name IN ('Vanguard', 'Vanguard') AND f.level = 6 AND f.name IN ('Interpose', 'Take the Blow');
UPDATE subclass_features f SET name='Endless Arsenal', description='Gain a 5th maneuver die. Once per turn when you score a critical hit or drop a creature to 0 HP, regain 1 maneuver die.', action_type=NULL, uses='1/turn', dice='maneuver die', approved_date=DATE '2026-10-16'
  FROM sub_classes s JOIN classes c ON c.id = s.class_id WHERE s.id = f.subclass_id AND c.name = 'Warrior' AND s.name IN ('Weapons Master ', 'Weaponmaster') AND f.level = 18 AND f.name IN ('Perfect Form', 'Endless Arsenal');
UPDATE subclass_features f SET name='Hushed Passage', description='Bonus action: become a whisper and move up to 30 ft through dim light or darkness without provoking, passing through creatures; you and allies within 5 ft of where you stop gain half cover until your next turn.', action_type='bonus', uses='At will', dice=NULL, approved_date=DATE '2026-10-16'
  FROM sub_classes s JOIN classes c ON c.id = s.class_id WHERE s.id = f.subclass_id AND c.name = 'Priest' AND s.name IN ('Whisper', 'Whisper') AND f.level = 14 AND f.name IN ('Shadow Step, Sacred', 'Hushed Passage');
UPDATE subclass_features f SET name='Vessel Leap', description='Bonus action, 1 Temper: teleport up to 30 ft to an unoccupied space within 5 ft of a creature you can see (any light).', action_type='bonus', uses='At will (1 Temper)', dice=NULL, approved_date=DATE '2026-10-16'
  FROM sub_classes s JOIN classes c ON c.id = s.class_id WHERE s.id = f.subclass_id AND c.name = 'Soul Smith' AND s.name IN ('Mark of Possession', 'Mark of Possession') AND f.level = 6 AND f.name IN ('Shadow Step', 'Vessel Leap');
UPDATE class_features f SET name='Oath''s Rebuke', description='Oath Channel, action: undead, fiends, or Hollow of your choice within 30 ft make a WIS save; on a failure they take 2d10 radiant (3d10 at 13, 4d10 at 23) and can''t willingly move closer to you for 1 minute (ends if damaged).', action_type='action', uses='1 Oath Channel', dice='2d10', approved_date=DATE '2026-10-16'
  FROM classes c WHERE c.id = f.class_id AND c.name = 'Paladin' AND f.level = 3 AND f.name IN ('Turn the Unholy / Bind the Hollow', 'Oath''s Rebuke');
UPDATE class_features f SET name='Thick Blood', description='While you wear no armor, your AC = 10 + STR modifier + CON modifier. No shield.', action_type=NULL, uses='Passive', dice=NULL, approved_date=DATE '2026-10-16'
  FROM classes c WHERE c.id = f.class_id AND c.name = 'Berserker' AND f.level = 1 AND f.name IN ('Unarmored Defense', 'Thick Blood');
UPDATE subclass_features f SET name='Fade to Nothing', description='1 per rest: when you Hide in dim light or darkness, you are invisible until the end of your next turn.', action_type=NULL, uses='1 per rest', dice=NULL, approved_date=DATE '2026-10-16'
  FROM sub_classes s JOIN classes c ON c.id = s.class_id WHERE s.id = f.subclass_id AND c.name = 'Assassin' AND s.name IN ('Ghostwalker', 'Ghostwalker') AND f.level = 14 AND f.name IN ('Vanish', 'Fade to Nothing');
UPDATE subclass_features f SET name='Ochre''s Second Dawn', description='1 per long rest, when you drop to 0 HP and aren''t killed: you are stable, and at the start of your next turn you regain HP equal to 2 x your Paladin level and stand up.', action_type=NULL, uses='1 per long rest', dice=NULL, approved_date=DATE '2026-10-16'
  FROM sub_classes s JOIN classes c ON c.id = s.class_id WHERE s.id = f.subclass_id AND c.name = 'Paladin' AND s.name IN ('Oath of Ochre', 'Oath of Ochre') AND f.level = 18 AND f.name IN ('Ochre''s Endurance', 'Ochre''s Second Dawn');
UPDATE class_features f SET name='Blood Debt', description='While raging, when you drop to 0 HP and aren''t killed, make a CON save (DC 10, +5 per use; resets on a short rest). On a success you stay conscious at 0 HP until the end of your next turn; if you deal damage before then you regain HP equal to your Berserker level, otherwise you fall unconscious.', action_type=NULL, uses='DC resets on short rest', dice=NULL, approved_date=DATE '2026-10-16'
  FROM classes c WHERE c.id = f.class_id AND c.name = 'Berserker' AND f.level = 11 AND f.name IN ('Relentless Rage', 'Blood Debt');
UPDATE class_features f SET name='Twin-Souled', description='Bonus action, 1 minute, 1 per long rest: your devil crosses over at once and acts on your initiative without raising Crossing; Strain can''t rise above 4 and Fray doesn''t apply; Soul Strike costs 0 Temper; once per turn when you and your devil both hit the same creature, it takes +2d8 force.', action_type='bonus', uses='1 per long rest', dice='2d8', approved_date=DATE '2026-10-16'
  FROM classes c WHERE c.id = f.class_id AND c.name = 'Soul Smith' AND f.level = 30 AND f.name IN ('Twin-Souled', 'Twin-Souled');
UPDATE class_features f SET name='Unclaimable', description='Immune to charmed and to possession; your soul can''t be stolen, swapped, trapped or claimed (including by your devil). When you''d be frightened, you can instead gain 1 Strain. Soulquake deals 8d8.', action_type=NULL, uses='Passive', dice='8d8', approved_date=DATE '2026-10-16'
  FROM classes c WHERE c.id = f.class_id AND c.name = 'Soul Smith' AND f.level = 25 AND f.name IN ('Unclaimable', 'Unclaimable');
UPDATE subclass_features f SET name='Hunger Tithe', description='Once per turn when a Hollow summon deals Hunger damage, you or another summon within 30 ft gains temporary HP equal to that damage.', action_type=NULL, uses='1/turn', dice='summon''s dice', approved_date=DATE '2026-10-16'
  FROM sub_classes s JOIN classes c ON c.id = s.class_id WHERE s.id = f.subclass_id AND c.name = 'Summoner' AND s.name IN ('Hollomancer', 'Hollowmancer') AND f.level = 6 AND f.name IN ('Shared Hunger', 'Hunger Tithe');
UPDATE class_features f SET name='Driving Point', description='Once per turn when you hit with a polearm on a natural 18 or 19, roll one extra weapon die and push the target 5 ft.', action_type=NULL, uses='1/turn', dice='+1 weapon die', approved_date=DATE '2026-10-16'
  FROM classes c WHERE c.id = f.class_id AND c.name = 'Lancer' AND f.level = 15 AND f.name IN ('Keen Point', 'Driving Point');
UPDATE class_features f SET name='Unstoppable', description='While raging you can''t be stunned or paralyzed, and only story-gated legends can knock you prone.', action_type=NULL, uses='Passive', dice=NULL, approved_date=DATE '2026-10-16'
  FROM classes c WHERE c.id = f.class_id AND c.name = 'Berserker' AND f.level = 25 AND f.name IN ('Unstoppable', 'Unstoppable');
UPDATE subclass_features f SET name='Rallying Refrain', description='Starting Countercharm ends frightened on allies within 30 ft, and each ally it frees gains temp HP equal to your CHA modifier + PB.', action_type=NULL, uses='At will', dice=NULL, approved_date=DATE '2026-10-16'
  FROM sub_classes s JOIN classes c ON c.id = s.class_id WHERE s.id = f.subclass_id AND c.name = 'Songsmith' AND s.name IN ('Warsong', 'Warsong') AND f.level = 6 AND f.name IN ('Fear Breaker', 'Rallying Refrain');
UPDATE subclass_features f SET name='Living Rampart', description='Bonus action, 1 minute, 1 per long rest: allies within 15 ft have three-quarters cover, you gain temp HP equal to your Knight level at the start of each turn, and once per turn you can Interpose without a reaction.', action_type='bonus', uses='1 per long rest', dice=NULL, approved_date=DATE '2026-10-16'
  FROM sub_classes s JOIN classes c ON c.id = s.class_id WHERE s.id = f.subclass_id AND c.name = 'Knight' AND s.name IN ('Shieldbearer', 'Shieldbearer') AND f.level = 28 AND f.name IN ('Living Rampart', 'Living Rampart');
UPDATE class_features f SET name='Diamond Soul', description='Proficiency in all saves. When you fail a save, spend 1 Focus to add 1d6 to it (can turn it into a success).', action_type=NULL, uses='Per Focus', dice='1d6', approved_date=DATE '2026-10-16'
  FROM classes c WHERE c.id = f.class_id AND c.name = 'Pugilist' AND f.level = 15 AND f.name IN ('Diamond Soul', 'Diamond Soul');
UPDATE subclass_levels sl SET description = f.name FROM subclass_features f WHERE f.subclass_id = sl.subclass_id AND f.level = sl.level AND sl.description IN ('Hold the Line','Shadow Step');

-- 3. Primordial Blessings (27)
INSERT INTO primordial_blessings (name, tree, prerequisite, description, action_type, uses, dice, repeatable_max, approved_date) VALUES
 ('Hearthblood','Ochre',NULL,'Max HP +2 per level (retroactive). When you spend Hit Dice, add your CON modifier once more per die.',NULL,NULL,NULL,1,DATE '2026-10-16'),
 ('Steady Bulwark','Ochre','proficiency with medium or heavy armor or a shield','+1 AC while wearing armor or holding a shield.',NULL,NULL,NULL,1,DATE '2026-10-16'),
 ('Swiftfoot','Ochre',NULL,'+10 ft walking speed; difficult terrain costs no extra movement on your first 10 ft each turn.',NULL,NULL,NULL,1,DATE '2026-10-16'),
 ('Mender''s Touch','Ochre','level 4, WIS or CHA 13','Action: a creature you touch regains 1d8 + PB + the creature''s level ÷ 4 HP.','action','PB per long rest','1d8',1,DATE '2026-10-16'),
 ('Warding Word','Ochre','level 8','Reaction when an ally within 30 ft is hit: it gains +PB AC against that attack (can turn it into a miss).','reaction','PB per long rest',NULL,1,DATE '2026-10-16'),
 ('Second Breath','Ochre','level 8, CON 13','+1 CON. Once per short rest, when you start your turn below half HP, regain 2d6 + CON modifier HP (no action).',NULL,'1 per short rest','2d6',1,DATE '2026-10-16'),
 ('Kindred Rally','Ochre','level 12','Bonus action: up to 3 allies within 30 ft gain temp HP = 5 + your level ÷ 2.','bonus','1 per short rest',NULL,1,DATE '2026-10-16'),
 ('Iron Resolve','Ochre',NULL,'+1 to one score; gain proficiency in a save you lack.',NULL,NULL,NULL,2,DATE '2026-10-16'),
 ('Unshaken','Ochre','level 16','Advantage on saves against charmed, frightened and stunned.',NULL,NULL,NULL,1,DATE '2026-10-16'),
 ('Heavy Hand','Umber','proficiency with a heavy or versatile weapon','Once per turn, when you hit with a two-handed or versatile weapon held in two hands, +PB damage.',NULL,'1/turn',NULL,1,DATE '2026-10-16'),
 ('Deadeye Draw','Umber','proficiency with a ranged weapon','Your ranged weapon attacks ignore half cover, and long range doesn''t give disadvantage.',NULL,NULL,NULL,1,DATE '2026-10-16'),
 ('Twin Fangs','Umber',NULL,'Off-hand attacks add your ability modifier to damage and can use non-light one-handed weapons.',NULL,NULL,NULL,1,DATE '2026-10-16'),
 ('Spell Edge','Umber','the Spellcasting feature','Once per turn, add your spellcasting modifier to one damage roll of a spell or cantrip.',NULL,'1/turn',NULL,1,DATE '2026-10-16'),
 ('Elemental Bite','Umber','the Spellcasting feature or level 8','Choose a damage type (fire, cold, lightning, acid, thunder, radiant, necrotic). Your damage of that type ignores resistance, and 1s on its damage dice count as 2s.',NULL,NULL,NULL,3,DATE '2026-10-16'),
 ('Crushing Momentum','Umber','level 8, STR 13','After moving 15 ft straight toward a target, your first melee hit deals +1d8 and pushes it 5 ft.',NULL,'1/turn','1d8',1,DATE '2026-10-16'),
 ('Finishing Blow','Umber','level 12','Once per turn, +1d10 damage to a creature that is below half its HP max.',NULL,'1/turn','1d10',1,DATE '2026-10-16'),
 ('Bleeding Cut','Umber','level 12','Once per turn on a weapon hit, the target bleeds for 1d6 at the start of its turns until it or an ally uses an action (Medicine DC = blessing DC).',NULL,'1/turn','1d6',1,DATE '2026-10-16'),
 ('Overwhelm','Umber','level 16, the Extra Attack frame','When you hit the same creature with two attacks in one turn, the second hit deals +2d6.',NULL,'1/turn','2d6',1,DATE '2026-10-16'),
 ('Night-Eyed','Sable',NULL,'Darkvision 60 ft (or +30 ft if you have it). Dim light doesn''t impose disadvantage on Perception.',NULL,NULL,NULL,1,DATE '2026-10-16'),
 ('Keen Wits','Sable',NULL,'+1 INT, WIS or CHA; proficiency in one skill and one tool.',NULL,NULL,NULL,2,DATE '2026-10-16'),
 ('Ever-Watchful','Sable',NULL,'+PB to initiative; you can''t be surprised while conscious.',NULL,NULL,NULL,1,DATE '2026-10-16'),
 ('Silver Tongue','Sable','CHA 13','Proficiency in Persuasion or Deception (expertise if already proficient). Once per long rest, reroll a failed CHA check.',NULL,'1 per long rest',NULL,1,DATE '2026-10-16'),
 ('Gravecaller','Sable','level 4','Action: ask one question of a corpse dead less than 10 days; it answers truthfully in up to 5 words.','action','1 per long rest',NULL,1,DATE '2026-10-16'),
 ('Death''s Margin','Sable','level 8','Death saves succeed on 9+; when you''re stabilized you regain 1 HP.',NULL,NULL,NULL,1,DATE '2026-10-16'),
 ('Many Faces','Sable','level 8','Action: change your appearance (not size) for 1 hour; Investigation (blessing DC) to see through it.','action','PB per long rest',NULL,1,DATE '2026-10-16'),
 ('Trickster''s Feint','Sable','level 12','Bonus action: make a Deception check against a creature''s Insight; on a success your next attack against it this turn has advantage and it can''t make opportunity attacks against you.','bonus','PB per long rest',NULL,1,DATE '2026-10-16'),
 ('Veilsight','Sable','level 16','You see invisible creatures within 10 ft, and once per long rest gain truesight 60 ft for 1 minute (bonus action).','bonus','1 per long rest',NULL,1,DATE '2026-10-16')
ON CONFLICT (name) DO UPDATE SET tree=EXCLUDED.tree, prerequisite=EXCLUDED.prerequisite, description=EXCLUDED.description, action_type=EXCLUDED.action_type, uses=EXCLUDED.uses, dice=EXCLUDED.dice, repeatable_max=EXCLUDED.repeatable_max;

-- 4. Boost frame: picks at 4/8/12/16/20/24/28, Cap Rise at 19/22/29, Primordial Ascent at 29, nothing at 26
DELETE FROM class_features WHERE feature_type = 'boost' AND name = 'Ability Boost' AND level IN (19, 22, 26, 29);
INSERT INTO class_features (class_id, level, name, description, feature_type, source, approved_date, sort_order, options, choice_count)
SELECT id, 4, 'Ability Boost', 'Choose one: an Ability Boost (+2 to one ability score, or +1 to two) or one Primordial Blessing (Ochre''s, Umber''s or Sable''s). No score can go above 20.', 'boost', 'new', DATE '2026-10-16', 50, ARRAY['Ability Boost','Hearthblood','Steady Bulwark','Swiftfoot','Mender''s Touch','Warding Word','Second Breath','Kindred Rally','Iron Resolve','Unshaken','Heavy Hand','Deadeye Draw','Twin Fangs','Spell Edge','Elemental Bite','Crushing Momentum','Finishing Blow','Bleeding Cut','Overwhelm','Night-Eyed','Keen Wits','Ever-Watchful','Silver Tongue','Gravecaller','Death''s Margin','Many Faces','Trickster''s Feint','Veilsight'], 1 FROM classes
ON CONFLICT (class_id, level, name) DO UPDATE SET description=EXCLUDED.description, feature_type='boost', options=EXCLUDED.options, choice_count=1, approved_date=EXCLUDED.approved_date;
