INSERT INTO class_features (class_id, level, name, description, feature_type, source, approved_date, sort_order)
SELECT id, 29, 'Cap Rise', 'Your ability score cap becomes 26. No pick at this level.', 'boost', 'new', DATE '2026-10-16', 50 FROM classes
ON CONFLICT (class_id, level, name) DO UPDATE SET description=EXCLUDED.description, options=NULL, choice_count=NULL;
INSERT INTO class_features (class_id, level, name, description, feature_type, source, approved_date, sort_order)
SELECT id, 29, 'Primordial Ascent', '+1 to one ability score (within the new cap of 26).', 'boost', 'new', DATE '2026-10-16', 51 FROM classes
ON CONFLICT (class_id, level, name) DO UPDATE SET description=EXCLUDED.description;
UPDATE class_levels SET description = regexp_replace(description, '(\s*\+\s*)?Ability Boost(\s*\+\s*)?', '', 'g') WHERE level IN (19, 22, 26, 29) AND description LIKE '%Ability Boost%';
UPDATE class_levels SET description = CASE WHEN coalesce(description,'') = '' THEN 'Cap Rise' ELSE description || ' + Cap Rise' END WHERE level IN (19, 22, 29) AND coalesce(description,'') NOT LIKE '%Cap Rise%';
UPDATE class_levels SET description = description || ' + Primordial Ascent' WHERE level = 29 AND description NOT LIKE '%Primordial Ascent%';
UPDATE class_levels SET description = CASE WHEN coalesce(description,'') = '' THEN 'Ability Boost or Blessing' ELSE description || ' + Ability Boost or Blessing' END WHERE level IN (20, 24, 28) AND coalesce(description,'') NOT LIKE '%Ability Boost%';
UPDATE class_levels SET description = '(no feature)' WHERE level = 26 AND coalesce(description,'') = '';

