COMMIT;
SELECT (SELECT count(*) FROM sub_classes WHERE name IN ('Weaponmaster','Hollowmancer','Oath of Shadows','Rite of the Archon','Rite of the Seraph','Rite of the Virtue')) AS renamed_subclasses,
       (SELECT count(*) FROM primordial_blessings) AS blessings,
       (SELECT count(*) FROM class_features WHERE name = 'Ability Boost') AS boost_rows,
       (SELECT count(*) FROM class_features WHERE name = 'Cap Rise') AS cap_rise_rows,
       (SELECT count(*) FROM class_features WHERE name = 'Primordial Ascent') AS ascent_rows,
       (SELECT count(*) FROM class_feature_options) AS options,
       (SELECT count(*) FROM class_features WHERE feature_type = 'choice' AND sort_order = 40) AS pool_rows;
